export function CommentThread({
  author = "{{author}}",
  topic = "{{topic}}",
  replyCount = {{replyCount}},
  resolved = {{resolved}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ maxWidth: 380, fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", border: "1px solid #24143020", borderRadius: 12, padding: "14px 16px", boxSizing: "border-box" }}>
      <article style={{ display: "flex", alignItems: "flex-start", gap: 10, opacity: resolved ? 0.6 : 1 }}>
        <span style={{ width: 30, height: 30, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: accent, color: "#FAF7F2", fontSize: 11, fontWeight: 700 }} aria-hidden="true">{author}</span>
        <div>
          <p style={{ margin: 0, fontWeight: 600 }}>{author}</p>
          <p style={{ margin: "2px 0 0" }}>{topic}</p>
        </div>
        {resolved && (
          <span style={{ marginLeft: "auto", background: accent, color: "#241430", fontSize: 11, fontWeight: 600, padding: "3px 8px", borderRadius: 999, whiteSpace: "nowrap" }}>Resolved</span>
        )}
      </article>
      <p style={{ margin: "10px 0 8px", fontSize: 12, color: "#24143080", paddingLeft: 40 }}>{replyCount} replies</p>
      <button type="button" style={{ marginLeft: 40, background: "transparent", border: `1.5px solid ${accent}`, color: "#241430", padding: "6px 12px", borderRadius: 8, fontSize: 13, fontWeight: 500, cursor: "pointer" }}>Reply</button>
    </div>
  );
}
